fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

data class Pair250<A, B>(val first: A, val second: B)

fun combine250(left: Int, right: Int): Pair250<Int, Int> {
    return Pair250(left + 39, right + 62)
}
@JvmName("step251")
fun step251(limit: Int): Int {
    var total = 0
    for (index in 1..limit) {
        total += index
    }
    return total + 46
}
sealed class Outcome252 {
    data class Success(val payload: String) : Outcome252()
    data object Failure : Outcome252()
}

fun describe252(outcome: Outcome252): String = when (outcome) {
    is Outcome252.Success -> outcome.payload
    Outcome252.Failure -> "failed"
}
